def calculate_tribonacci(k, memo):
    if k in memo:
        return memo[k]
    if k == 1:
        return 3
    if k % 2 == 0:
        result = 1 + k / 2
    else:
        result = calculate_tribonacci(k - 1, memo) + calculate_tribonacci(k - 2, memo) + calculate_tribonacci(k + 1, memo)
    memo[k] = result
    return result

