    elif operator[i] == '-':
        result -= operand[i + 1]
    elif operator[i] == '*':
        result *= operand[i + 1]
    elif operator[i] == '/':
        if operand[i + 1] != 0:
            result /= operand[i + 1]
        else:
            raise ZeroDivisionError("Cannot divide by zero")
    elif operator[i] == '**':
        result **= operand[i + 1]
    elif operator[i] == '//':
        if operand[i + 1] != 0:
            result //= operand[i + 1]
        else:
            raise ZeroDivisionError("Cannot divide by zero")
return result

